import React, { createContext, useCallback, useContext, useMemo, useState } from 'react';

const STORAGE_KEY = 'eventsphere_college';

const CollegeContext = createContext(null);

const readStoredCollege = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};

export const CollegeProvider = ({ children }) => {
  const [college, setCollegeState] = useState(readStoredCollege);
  const [selectorOpen, setSelectorOpen] = useState(false);

  const selectCollege = useCallback((value) => {
    setCollegeState(value);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
    setSelectorOpen(false);
  }, []);

  const openSelector = useCallback(() => setSelectorOpen(true), []);
  const closeSelector = useCallback(() => setSelectorOpen(false), []);

  const value = useMemo(
    () => ({
      college,
      selectCollege,
      openSelector,
      closeSelector,
      // Popup is forced on first visit (no college yet) or when user asks to change.
      isSelectorVisible: !college || selectorOpen,
    }),
    [college, selectorOpen, selectCollege, openSelector, closeSelector]
  );

  return <CollegeContext.Provider value={value}>{children}</CollegeContext.Provider>;
};

export const useCollege = () => {
  const ctx = useContext(CollegeContext);
  if (!ctx) throw new Error('useCollege must be used within a CollegeProvider');
  return ctx;
};
